# 답변 후보: (길이, 실제로 도움이 된 정도 0~1)
cands = {"짧고 정확": (40, 0.9), "길고 정확": (300, 0.8),
         "길고 그럴듯한 오답": (400, 0.1), "거절": (10, 0.0)}
proxy    = lambda L, h: L / 100            # 실수로 '길수록 좋다'를 보상으로 씀
intended = lambda L, h: h - 0.001 * L      # 원래 뜻: 도움 되고 간결하게
for name, f in [("proxy", proxy), ("intended", intended)]:
    scores = {k: round(f(*v), 3) for k, v in cands.items()}
    print(name, scores, "→", max(scores, key=scores.get))

from math import comb
def p_at_least(k, n, p=0.5):           # 판정자가 동전 던지기보다 나은가?
    return sum(comb(n, i) * p**i * (1-p)**(n-i) for i in range(k, n+1))
for k, n in [(6, 10), (60, 100), (70, 100)]:
    print(f"{k}/{n} 맞힘 → 우연일 확률 {p_at_least(k, n):.4f}")

import numpy as np, timeit
def slow_matmul(x, w):
    n, k = x.shape; m = w.shape[1]; y = np.zeros((n, m))
    for i in range(n):
        for j in range(m):
            for t in range(k):
                y[i, j] += x[i, t] * w[t, j]
    return y
for N in (16, 64):
    x, w = np.random.randn(N, N), np.random.randn(N, N)
    assert np.allclose(slow_matmul(x, w), x @ w)
    tp = timeit.timeit(lambda: slow_matmul(x, w), number=1)
    tn = timeit.timeit(lambda: x @ w, number=100) / 100
    print(f"N={N}: python {tp*1e3:.2f} ms, numpy {tn*1e6:.2f} us, x{tp/tn:,.0f}")
